/**
 * ISS-12168: every exported `*ErrorCode` object in the shared contract
 * packages is in the `request_completed` `error_code` set. A new one that is
 * not added to `REQUEST_ERROR_CODE_SOURCES` turns this red instead of being
 * dropped from the log.
 */
import { describe, expect, it } from "vitest";
import { readResponseErrorCode } from "@/lib/observability/request-error-code";

const contractModules = import.meta.glob([
  "../../../../packages/api/src/types/**/*.ts",
  "../../../../packages/loops-api/src/**/*.ts",
  "!**/*.test.ts",
  "!**/__tests__/**",
]);

/**
 * These import `@repo/crewd`, which `apps/api` does not depend on, so
 * `apps/api` cannot answer a code from them.
 */
const NOT_IMPORTABLE_FROM_API = [
  "../../../../packages/api/src/types/convert-install.ts",
  "../../../../packages/api/src/types/harness-conversion.ts",
];

const ERROR_CODE_EXPORT = /ErrorCode$/;

const loaded = await Promise.all(
  Object.entries(contractModules).map(async ([modulePath, load]) => {
    try {
      return { modulePath, imported: true, exports: await load() };
    } catch {
      return { modulePath, imported: false, exports: undefined };
    }
  })
);

const errorCodeObjects = loaded.flatMap(({ modulePath, exports }) =>
  Object.entries(typeof exports === "object" && exports !== null ? exports : {})
    .filter(
      (entry): entry is [string, Record<string, string>] =>
        ERROR_CODE_EXPORT.test(entry[0]) && isStringRecord(entry[1])
    )
    .map(([name, codes]) => ({ name, modulePath, codes }))
);

describe("request_completed error_code inventory (ISS-12168)", () => {
  it("imports every contract module except the named ones", () => {
    const unimported = loaded
      .filter(({ imported }) => !imported)
      .map(({ modulePath }) => modulePath)
      .sort();

    expect(unimported).toEqual(NOT_IMPORTABLE_FROM_API);
  });

  it("walks both contract packages", () => {
    const names = errorCodeObjects.map(({ name }) => name);

    expect(names).toContain("AuthErrorCode");
    expect(names).toContain("LoopEventIngestErrorCode");
  });

  it.each(errorCodeObjects)(
    "$name ($modulePath) is in the error_code set",
    async ({ codes }) => {
      const missing: string[] = [];
      for (const code of Object.values(codes)) {
        const logged = await readResponseErrorCode(
          Response.json({ code }, { status: 403 })
        );
        if (logged !== code) {
          missing.push(code);
        }
      }

      expect(missing).toEqual([]);
    }
  );
});

function isStringRecord(value: unknown): value is Record<string, string> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const values = Object.values(value);
  return values.length > 0 && values.every((item) => typeof item === "string");
}

import assert from "node:assert/strict";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterEach, describe, test } from "vitest";
import {
  materializeAgents,
  materializeCriticGates,
} from "../src/server/operations/symphony-loop.js";

const tempPaths: string[] = [];

afterEach(async () => {
  for (const tempPath of tempPaths.splice(0)) {
    await fs.rm(tempPath, { recursive: true, force: true });
  }
});

function makeTempDir(): string {
  const dir = path.join(
    os.tmpdir(),
    `ctx-mat-test-${Date.now()}-${Math.random().toString(36).slice(2)}`
  );
  mkdirSync(dir, { recursive: true });
  tempPaths.push(dir);
  return dir;
}

// --- materializeAgents ---

describe("materializeAgents", () => {
  test("writes agent files to .claude/agents/{slug}.md", async () => {
    const dir = makeTempDir();
    const agents = [
      {
        slug: "api-expert",
        name: "API Expert",
        prompt: "---\nname: api-expert\n---\nYou are an API expert.\n",
      },
      {
        slug: "frontend-arch",
        name: "Frontend Architect",
        prompt:
          "---\nname: frontend-arch\n---\nYou are a frontend architect.\n",
      },
    ];

    const count = await materializeAgents(dir, agents);

    assert.equal(count, 2);
    const file1 = readFileSync(
      path.join(dir, ".claude", "agents", "api-expert.md"),
      "utf-8"
    );
    assert.equal(file1, "---\nname: api-expert\n---\nYou are an API expert.\n");
    const file2 = readFileSync(
      path.join(dir, ".claude", "agents", "frontend-arch.md"),
      "utf-8"
    );
    assert.equal(
      file2,
      "---\nname: frontend-arch\n---\nYou are a frontend architect.\n"
    );
  });

  test("appends trailing newline when missing", async () => {
    const dir = makeTempDir();
    const agents = [
      {
        slug: "test-agent",
        name: "Test",
        prompt: "---\nname: test-agent\n---\nNo trailing newline",
      },
    ];

    await materializeAgents(dir, agents);

    const content = readFileSync(
      path.join(dir, ".claude", "agents", "test-agent.md"),
      "utf-8"
    );
    assert.ok(content.endsWith("\n"));
  });

  test("does not double trailing newline", async () => {
    const dir = makeTempDir();
    const agents = [
      { slug: "test-agent", name: "Test", prompt: "prompt content\n" },
    ];

    await materializeAgents(dir, agents);

    const content = readFileSync(
      path.join(dir, ".claude", "agents", "test-agent.md"),
      "utf-8"
    );
    assert.equal(content, "prompt content\n");
  });

  test("returns 0 and writes nothing for empty array", async () => {
    const dir = makeTempDir();
    const count = await materializeAgents(dir, []);

    assert.equal(count, 0);
    assert.equal(existsSync(path.join(dir, ".claude", "agents")), false);
  });

  test("preserves non-conflicting repo agent files", async () => {
    const dir = makeTempDir();
    const agentsDir = path.join(dir, ".claude", "agents");
    mkdirSync(agentsDir, { recursive: true });
    writeFileSync(path.join(agentsDir, "repo-only.md"), "repo agent content\n");

    const agents = [
      { slug: "db-agent", name: "DB Agent", prompt: "db prompt\n" },
    ];

    await materializeAgents(dir, agents);

    assert.equal(
      readFileSync(path.join(agentsDir, "repo-only.md"), "utf-8"),
      "repo agent content\n"
    );
    assert.equal(
      readFileSync(path.join(agentsDir, "db-agent.md"), "utf-8"),
      "db prompt\n"
    );
  });

  test("sanitizes path-traversal slugs and blocks escapes", async () => {
    const dir = makeTempDir();
    const agents = [
      { slug: "../../etc/evil", name: "Evil", prompt: "pwned\n" },
      { slug: "../escape", name: "Escape", prompt: "escaped\n" },
      { slug: "good-agent", name: "Good", prompt: "safe\n" },
    ];

    const count = await materializeAgents(dir, agents);

    assert.equal(existsSync(path.join(dir, "..", "etc", "evil.md")), false);
    assert.equal(existsSync(path.join(dir, "..", "escape.md")), false);
    assert.equal(
      readFileSync(
        path.join(dir, ".claude", "agents", "good-agent.md"),
        "utf-8"
      ),
      "safe\n"
    );
    assert.ok(count <= 3);
  });

  test("skips agents with missing or non-string prompt", async () => {
    const dir = makeTempDir();
    const agents = [
      {
        slug: "no-prompt",
        name: "No Prompt",
        prompt: null as unknown as string,
      },
      { slug: "valid", name: "Valid", prompt: "content\n" },
    ];

    const count = await materializeAgents(dir, agents);

    assert.equal(count, 1);
    assert.equal(
      existsSync(path.join(dir, ".claude", "agents", "no-prompt.md")),
      false
    );
    assert.equal(
      readFileSync(path.join(dir, ".claude", "agents", "valid.md"), "utf-8"),
      "content\n"
    );
  });

  test("overwrites conflicting repo agent files (DB wins)", async () => {
    const dir = makeTempDir();
    const agentsDir = path.join(dir, ".claude", "agents");
    mkdirSync(agentsDir, { recursive: true });
    writeFileSync(
      path.join(agentsDir, "shared-agent.md"),
      "old repo version\n"
    );

    const agents = [
      {
        slug: "shared-agent",
        name: "Shared Agent",
        prompt: "new DB version\n",
      },
    ];

    await materializeAgents(dir, agents);

    assert.equal(
      readFileSync(path.join(agentsDir, "shared-agent.md"), "utf-8"),
      "new DB version\n"
    );
  });
});

// --- materializeCriticGates ---

describe("materializeCriticGates", () => {
  test("writes critic-gates.json for matching repo", async () => {
    const dir = makeTempDir();
    const repoConfigs = [
      {
        repoFullName: "org/repo-a",
        criticGates: { version: 1, gates: ["security"] },
      },
      {
        repoFullName: "org/repo-b",
        criticGates: { version: 2, gates: ["perf"] },
      },
    ];

    const wrote = await materializeCriticGates(dir, "org/repo-a", repoConfigs);

    assert.equal(wrote, true);
    const content = JSON.parse(
      readFileSync(
        path.join(dir, ".closedloop-ai", "settings", "critic-gates.json"),
        "utf-8"
      )
    );
    assert.deepEqual(content, { version: 1, gates: ["security"] });
  });

  test("returns false when no config matches repoFullName", async () => {
    const dir = makeTempDir();
    const repoConfigs = [
      { repoFullName: "org/other-repo", criticGates: { version: 1 } },
    ];

    const wrote = await materializeCriticGates(dir, "org/my-repo", repoConfigs);

    assert.equal(wrote, false);
    assert.equal(
      existsSync(path.join(dir, ".closedloop-ai", "settings")),
      false
    );
  });

  test("returns false for empty repoConfigs array", async () => {
    const dir = makeTempDir();
    const wrote = await materializeCriticGates(dir, "org/repo", []);

    assert.equal(wrote, false);
  });

  test("overwrites existing critic-gates.json", async () => {
    const dir = makeTempDir();
    const settingsDir = path.join(dir, ".closedloop-ai", "settings");
    mkdirSync(settingsDir, { recursive: true });
    writeFileSync(path.join(settingsDir, "critic-gates.json"), '{"old": true}');

    const repoConfigs = [
      { repoFullName: "org/repo", criticGates: { new: true } },
    ];

    await materializeCriticGates(dir, "org/repo", repoConfigs);

    const content = JSON.parse(
      readFileSync(path.join(settingsDir, "critic-gates.json"), "utf-8")
    );
    assert.deepEqual(content, { new: true });
  });

  test("writes JSON with trailing newline", async () => {
    const dir = makeTempDir();
    const repoConfigs = [{ repoFullName: "org/repo", criticGates: { v: 1 } }];

    await materializeCriticGates(dir, "org/repo", repoConfigs);

    const raw = readFileSync(
      path.join(dir, ".closedloop-ai", "settings", "critic-gates.json"),
      "utf-8"
    );
    assert.ok(raw.endsWith("\n"));
  });
});

import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, describe, test } from "vitest";
import { ActivityLogStore } from "../src/main/diagnostics/activity-log-store.js";

const tempDirs: string[] = [];

afterEach(() => {
  for (const dir of tempDirs.splice(0)) {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

function makeTempDir(): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "activity-log-test-"));
  tempDirs.push(dir);
  return dir;
}

function writeStoreFile(dir: string, name: string, events: unknown[]): void {
  fs.writeFileSync(path.join(dir, `${name}.json`), JSON.stringify({ events }));
}

function readStoreFile(dir: string, name: string): { events: unknown[] } {
  return JSON.parse(fs.readFileSync(path.join(dir, `${name}.json`), "utf-8"));
}

function makeEvent(overrides: Record<string, unknown> = {}) {
  return {
    id: `test-${Math.random().toString(36).slice(2)}`,
    timestamp: new Date().toISOString(),
    method: "GET",
    path: "/api/test",
    statusCode: 200,
    durationMs: 10,
    ...overrides,
  };
}

function createStore(dir: string, name: string, maxEntries = 200) {
  return new ActivityLogStore({ maxEntries, cwd: dir, name });
}

// --- body sanitization via add() ---

describe("ActivityLogStore body sanitization", () => {
  test("deletes raw bodies and preserves safe size metadata", () => {
    const dir = makeTempDir();
    const store = createStore(dir, "sanitize-bodies", 10);
    const event = store.add({
      timestamp: new Date().toISOString(),
      method: "POST",
      path: "/api/test",
      statusCode: 200,
      durationMs: 5,
      requestBody: "short body",
      responseBody: '{"ok": true}',
      requestSizeBytes: 10,
      responseSizeBytes: 12,
    });

    assert.equal(Object.hasOwn(event, "requestBody"), false);
    assert.equal(Object.hasOwn(event, "responseBody"), false);
    assert.equal(event.requestSizeBytes, 10);
    assert.equal(event.responseSizeBytes, 12);
  });

  test("does not retain large raw bodies", () => {
    const dir = makeTempDir();
    const store = createStore(dir, "sanitize-large", 10);
    const largeBody = "x".repeat(20_000);
    const event = store.add({
      timestamp: new Date().toISOString(),
      method: "POST",
      path: "/api/test",
      statusCode: 200,
      durationMs: 5,
      requestBody: largeBody,
      responseBody: largeBody,
    });

    assert.equal(Object.hasOwn(event, "requestBody"), false);
    assert.equal(Object.hasOwn(event, "responseBody"), false);
  });

  test("keeps safe events unchanged", () => {
    const dir = makeTempDir();
    const store = createStore(dir, "sanitize-safe", 10);
    const event = store.add({
      timestamp: new Date().toISOString(),
      method: "GET",
      path: "/api/test",
      statusCode: 200,
      durationMs: 5,
    });

    assert.equal(Object.hasOwn(event, "requestBody"), false);
    assert.equal(Object.hasOwn(event, "responseBody"), false);
  });
});

// --- Constructor migration ---

describe("ActivityLogStore startup migration", () => {
  test("deletes raw bodies from persisted events on startup", () => {
    const dir = makeTempDir();
    const name = "migrate-bodies";
    const largeBody = "y".repeat(20_000);
    writeStoreFile(dir, name, [
      makeEvent({
        requestBody: largeBody,
        responseBody: largeBody,
        requestSizeBytes: 20_000,
      }),
      makeEvent({
        requestBody: "small",
        responseBody: "small",
        responseSizeBytes: 5,
      }),
    ]);

    const store = createStore(dir, name);
    const events = store.list() as Record<string, unknown>[];

    assert.equal(events.length, 2);
    assert.equal(Object.hasOwn(events[0], "requestBody"), false);
    assert.equal(Object.hasOwn(events[0], "responseBody"), false);
    assert.equal(events[0].requestSizeBytes, 20_000);
    assert.equal(Object.hasOwn(events[1], "requestBody"), false);
    assert.equal(Object.hasOwn(events[1], "responseBody"), false);
    assert.equal(events[1].responseSizeBytes, 5);

    // Verify the sanitized data was persisted to disk
    const persisted = readStoreFile(dir, name);
    const persistedEvents = persisted.events as Record<string, unknown>[];
    assert.equal(Object.hasOwn(persistedEvents[0], "requestBody"), false);
    assert.equal(Object.hasOwn(persistedEvents[0], "responseBody"), false);
    assert.equal(persistedEvents[0].requestSizeBytes, 20_000);
    assert.equal(Object.hasOwn(persistedEvents[1], "requestBody"), false);
    assert.equal(Object.hasOwn(persistedEvents[1], "responseBody"), false);
  });

  test("trims event count to maxEntries on startup", () => {
    const dir = makeTempDir();
    const name = "migrate-count";
    const events = Array.from({ length: 50 }, (_, i) =>
      makeEvent({ id: `evt-${i}` })
    );
    writeStoreFile(dir, name, events);

    const store = createStore(dir, name, 10);
    assert.equal(store.list().length, 10);

    // Verify persisted file was trimmed too
    const persisted = readStoreFile(dir, name);
    assert.equal((persisted.events as unknown[]).length, 10);
  });

  test("does not rewrite file when nothing needs migration", () => {
    const dir = makeTempDir();
    const name = "migrate-noop";
    writeStoreFile(dir, name, [makeEvent({ requestSizeBytes: 5 })]);
    const statBefore = fs.statSync(path.join(dir, `${name}.json`));

    createStore(dir, name);

    const statAfter = fs.statSync(path.join(dir, `${name}.json`));
    assert.equal(statAfter.mtimeMs, statBefore.mtimeMs);
  });
});

// --- maxEntries enforcement ---

describe("ActivityLogStore maxEntries", () => {
  test("caps events at maxEntries when adding", () => {
    const dir = makeTempDir();
    const store = createStore(dir, "max-entries", 3);
    for (let i = 0; i < 5; i++) {
      store.add({
        timestamp: new Date().toISOString(),
        method: "GET",
        path: `/api/test/${i}`,
        statusCode: 200,
        durationMs: 1,
      });
    }

    assert.equal(store.list().length, 3);
    assert.equal(store.list()[0].path, "/api/test/4");
  });
});

#!/usr/bin/env node
// ISS-4594: aggregate per-package vitest coverage plus the desktop dual-lane
// summary into one repo-wide report (global %, per-package table, desktop
// partitions) at coverage/coverage-report.{json,md}.
//
// Correctness rule inherited from the trace-test-coverage census (ISS-4648):
// only FULL istanbul maps (coverage-final.json) are unioned — a
// coverage-summary.json carries no branch identities and cannot be merged.
// A package whose map is missing or corrupt is reported as "not measured",
// never silently blended in or fabricated as 0%.
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import {
  aggregateWorkspaceCoverage,
  renderReportMarkdown,
} from "./aggregate-lib.mjs";
import {
  DESKTOP_PATH,
  discoverCoveragePackages,
  INTEGRATION_COVERAGE_MAP,
  INTEGRATION_COVERAGE_SCRIPT,
} from "./discover-packages.mjs";

const repoRoot = resolve(fileURLToPath(new URL("../..", import.meta.url)));
const OUTPUT_DIR = join(repoRoot, "coverage");
const MAIN_COVERAGE_MAP = "coverage/coverage-final.json";
const DESKTOP_SUMMARY = join(
  repoRoot,
  DESKTOP_PATH,
  "coverage/merged/coverage-summary.json"
);

function readPackageMap(relativeDir, mapFile) {
  const mapPath = join(repoRoot, relativeDir, mapFile);
  if (!existsSync(mapPath)) {
    return { status: "missing" };
  }
  try {
    const parsed = JSON.parse(readFileSync(mapPath, "utf8"));
    if (
      typeof parsed !== "object" ||
      parsed === null ||
      Array.isArray(parsed)
    ) {
      return { status: "corrupt", detail: "not an object" };
    }
    const keys = Object.keys(parsed);
    if (keys.length === 0) {
      return { status: "corrupt", detail: "empty map (no file entries)" };
    }
    if (parsed.total?.branches) {
      return {
        status: "corrupt",
        detail: "summary map, not a full istanbul map",
      };
    }
    const sample = parsed[keys[0]];
    if (
      typeof sample !== "object" ||
      !("b" in sample || "branchMap" in sample || "statementMap" in sample)
    ) {
      return {
        status: "corrupt",
        detail: "entries lack Istanbul structure (b/branchMap/statementMap)",
      };
    }
    return { status: "ok", parsed };
  } catch (error) {
    return { status: "corrupt", detail: error.message };
  }
}

function readDesktopSummary() {
  if (!existsSync(DESKTOP_SUMMARY)) {
    return null;
  }
  try {
    return JSON.parse(readFileSync(DESKTOP_SUMMARY, "utf8"));
  } catch (error) {
    console.error(
      `[coverage-aggregate] desktop summary is corrupt (${error.message}) — desktop reported as not measured`
    );
    return null;
  }
}

/**
 * Everything that changes what the GLOBAL figure means, independent of the
 * numbers themselves — the workspace equivalent of the desktop lane's own
 * method identity, which only ever described the desktop partitions.
 *
 * `nodeMajor` because the instrumenter's output moves with it, and
 * `aggregationHash` because the merge/attribution semantics behind every count
 * live in exactly these two modules: change how maps are unioned, how a file is
 * attributed to a package, or which branch slots are counted, and the same tree
 * yields a different percentage. The measured PACKAGE SET is not folded in here
 * — the render compares it directly, and it belongs on the report where a
 * reader can see it.
 *
 * `createHash` rather than the desktop lane's `stableContentHash`: this module
 * must not take a dependency on a desktop-app script (see aggregate-lib.mjs on
 * the same boundary), and the stdlib does the whole job.
 */
function buildGlobalMethod() {
  const sources = [
    join(repoRoot, "scripts/coverage/aggregate-lib.mjs"),
    join(
      repoRoot,
      ".agents/skills/trace-test-coverage/scripts/trace-coverage-census.mjs"
    ),
  ];
  return {
    nodeMajor: Number(process.version.slice(1).split(".")[0]),
    aggregationHash: createHash("sha256")
      .update(sources.map((path) => readFileSync(path, "utf8")).join("\n"))
      .digest("hex"),
  };
}

const packages = discoverCoveragePackages(repoRoot);
const packageMaps = packages.map((pkg) => ({
  ...pkg,
  maps: [MAIN_COVERAGE_MAP, ...(pkg.additionalMaps ?? [])].map((file) => ({
    file,
    ...readPackageMap(pkg.dir, file),
  })),
}));
for (const pkg of packageMaps) {
  for (const map of pkg.maps) {
    if (map.status !== "ok") {
      console.error(
        `[coverage-aggregate] ${pkg.name}: coverage map ${map.file} ${map.status}${map.detail ? ` (${map.detail})` : ""} — reported as not measured${missingIntegrationMapHint(pkg.name, map)}`
      );
    }
  }
}

const parsedOrNull = (map) => (map.status === "ok" ? map.parsed : null);
const report = aggregateWorkspaceCoverage({
  entries: packageMaps.map((pkg) => ({
    name: pkg.name,
    dir: pkg.dir,
    parsed: parsedOrNull(pkg.maps[0]),
    additionalMaps: pkg.maps.slice(1).map(parsedOrNull),
  })),
  desktopSummary: readDesktopSummary(),
  desktopDir: DESKTOP_PATH,
  canonicalPath: (rawPath) => {
    const absolute = resolve(rawPath);
    if (!absolute.startsWith(repoRoot + sep)) {
      return null;
    }
    return absolute
      .slice(repoRoot.length + 1)
      .split(sep)
      .join("/");
  },
  generatedAt: new Date().toISOString(),
  globalMethod: buildGlobalMethod(),
});

mkdirSync(OUTPUT_DIR, { recursive: true });
writeFileSync(
  join(OUTPUT_DIR, "coverage-report.json"),
  `${JSON.stringify(report, null, 2)}\n`
);
const markdown = renderReportMarkdown(report);
writeFileSync(join(OUTPUT_DIR, "coverage-report.md"), markdown);
console.log(markdown);

/**
 * `pnpm coverage:report` never runs the integration lane, and the unit lane's
 * vitest `coverage.clean` deletes `coverage/`, integration map included, so
 * locally this map is missing unless the lane ran after the unit run.
 */
function missingIntegrationMapHint(name, map) {
  if (map.file !== INTEGRATION_COVERAGE_MAP || map.status !== "missing") {
    return "";
  }
  return `. Run \`RUN_DB_INTEGRATION_TESTS=true pnpm --filter=${name} ${INTEGRATION_COVERAGE_SCRIPT}\` with DATABASE_URL on a migrated database, after the unit coverage run, then rerun \`node scripts/coverage/aggregate.mjs\``;
}
